// Python string semantics that differ from JavaScript's, for ported code that
// must give byte-identical results. Each helper is golden-tested against
// Python output (tests/fixtures/python_strings_golden.json, generated by
// parity-tools/golden/python_strings.py), and numeric helpers golden-tested
// with tests/fixtures/risk_golden.json (parity-tools/golden/risk_cases.py).

import { PythonError } from './pythonJson.js';

// Python str.isspace() is true for exactly these code points (Python 3.12,
// Unicode 15.0). Compared with JS trim(): Python also strips U+001C–U+001F
// and U+0085, and does NOT strip U+FEFF (byte-order mark).
const PY_WHITESPACE =
  '\\t\\n\\x0B\\x0C\\r\\x1C-\\x20\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000';
const LEADING = new RegExp(`^[${PY_WHITESPACE}]+`, 'u');
const TRAILING = new RegExp(`[${PY_WHITESPACE}]+$`, 'u');

/**
 * Python `str.strip()` with no arguments.
 *
 * @param {string} value
 * @returns {string}
 */
export function pyStrip(value) {
  return value.replace(LEADING, '').replace(TRAILING, '');
}

/**
 * Python `str.lower()`. JS toLowerCase() applies the same Unicode full
 * lower-case mapping (including 'İ' → 'i̇' and the context-sensitive final
 * sigma); the golden test checks every code point Python lower-cases.
 *
 * @param {string} value
 * @returns {string}
 */
export function pyLower(value) {
  return value.toLowerCase();
}

// ─── Numbers (Phase 5: the seriousness rules, R-CHAT-02/04/05) ───

// float() maps every non-ASCII whitespace character to a space and every
// Unicode decimal digit (category Nd) to its ASCII digit, keeps ASCII as is,
// then strips only ASCII whitespace. So '\u2003 0.9' parses but '\x1c0.9' doesn't.
// Python parity: CPython Objects/unicodeobject.c _PyUnicode_TransformDecimalAndSpaceToASCII
const NON_ASCII_SPACE = /^[\x85\xA0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]$/u;
const DECIMAL_DIGIT = /^\p{Nd}$/u;
const FLOAT_LITERAL =
  /^[+-]?(?:(?:[0-9](?:_?[0-9])*)?\.[0-9](?:_?[0-9])*|[0-9](?:_?[0-9])*\.?)(?:[eE][+-]?[0-9](?:_?[0-9])*)?$/;
const SPECIAL = /^([+-]?)(inf|infinity|nan)$/i;

/**
 * The value of a Unicode decimal digit. Unicode assigns every run of Nd
 * characters as consecutive 0-9 sequences, so the value is the position
 * within the run, modulo 10.
 *
 * @param {number} cp a code point in category Nd
 * @returns {number}
 */
export function decimalDigitValue(cp) {
  let start = cp;
  while (DECIMAL_DIGIT.test(String.fromCodePoint(start - 1))) start -= 1;
  return (cp - start) % 10;
}

/** The string float()/int() actually parse: Unicode digits → ASCII, Unicode spaces → ' ', ASCII stripped. */
function toAsciiNumber(text) {
  let ascii = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) ascii += ch;
    else if (NON_ASCII_SPACE.test(ch)) ascii += ' ';
    else if (DECIMAL_DIGIT.test(ch)) ascii += String(decimalDigitValue(cp));
    else ascii += '?'; // never valid
  }
  return ascii.replace(/^[ \t\n\v\f\r]+|[ \t\n\v\f\r]+$/g, '');
}

function floatFromString(text) {
  const s = toAsciiNumber(text);
  const special = SPECIAL.exec(s);
  if (special) return special[2].toLowerCase() === 'nan' ? NaN : special[1] === '-' ? -Infinity : Infinity;
  if (!FLOAT_LITERAL.test(s)) throw new PythonError('ValueError', 'could not convert string to float');
  return Number(s.replaceAll('_', '')); // both correctly rounded; overflow → ±inf like Python
}
